use std::fs
use std::env

fn pad(n: int) -> string {
    let mut s = "${n}"
    while s.len() < 6 {
        s = " " + s
    }
    s
}

fn emit(content: string, number: bool, counter: int) -> int {
    let mut c = counter
    if !number {
        print(content)
        return c
    }
    let mut parts: Vec<string> = content.split("\n").collect()
    if content.ends_with("\n") || content.len() == 0 {
        parts.pop()
    }
    for p in parts {
        c += 1
        println(pad(c) + "\t" + p)
    }
    c
}

fn main() {
    let mut number = false
    let mut files: Vec<string> = []
    let mut first = true
    for a in env::args() {
        if first {
            first = false
            continue
        }
        if a == "-n" {
            number = true
        } else {
            files.push(a)
        }
    }
    let mut counter = 0
    let mut status = 0
    if files.len() == 0 {
        let text = fs::read_to_string("/dev/stdin").unwrap_or("")
        counter = emit(text, number, counter)
    } else {
        for f in files {
            match fs::read_to_string(f) {
                Ok(t) => { counter = emit(t, number, counter) }
                Err(_) => {
                    println("cat: ${f}: No such file")
                    status = 1
                }
            }
        }
    }
    if status != 0 {
        std::process::exit(status)
    }
}

